const crypto = require('crypto');
const canonical = value => Array.isArray(value) ? `[${value.map(canonical).join(',')}]` : (value !== null && typeof value === 'object' ? `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical(value[key])}`).join(',')}}` : JSON.stringify(value));
return $input.all().map((item, index) => {
  const input = item.json;
  const payload = {};
  const key_id = $env.INTERNAL_STEP_KEY_ID;
  const secret = $env.INTERNAL_STEP_SECRET;
  if (!key_id || !secret || secret.length < 32) throw new Error('internal_signer_unconfigured');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const nonce = crypto.randomUUID();
  const message = [key_id, timestamp, nonce, 'POST', '/discovery/runs', canonical(payload)].join('\n');
  const signature = crypto.createHmac('sha256', secret).update(message).digest('hex');
  return {json: {payload, internal_auth: {key_id, timestamp, nonce, signature}}, pairedItem: {item: index}};
});

